1: # Licensed under the Apache-2.0 license
2: # SPDX-License-Identifier: Apache-2.0
3: {
4:   description = "Mjolnir: AI Security Analysis Tool";
5: 
6:   inputs = {
7:     nixpkgs.url = "github:nixos/nixpkgs?ref=nixos-unstable";
8: 
9:     # Local Project Flakes (providing hermetic compiler environments)
10:     opentitan-env.url = "path:./projects/opentitan/nix";
11:     caliptra-sw-env.url = "path:./projects/caliptra-sw/nix";
12:     caliptra-mcu-sw-env.url = "path:./projects/caliptra-mcu-sw/nix";
13:     caliptra-dpe-env.url = "path:./projects/caliptra-dpe/nix";
14:     tests-env.url = "path:./projects/tests/nix";
15:   };
16: 
17:   outputs = { self, nixpkgs, opentitan-env, caliptra-sw-env, caliptra-mcu-sw-env, caliptra-dpe-env, tests-env }:
18:     let
19:       supportedSystems = [ "x86_64-linux" "aarch64-linux" ];
20:       forAllSystems = nixpkgs.lib.genAttrs supportedSystems;
21:       nixpkgsFor = forAllSystems (system: import nixpkgs { inherit system; });
22: 
23:       autodiscoverJobs = import ./nix/discovery.nix;
24:     in
25:     {
26:       packages = forAllSystems (system:
27:         let
28:           pkgs = nixpkgsFor.${system};
29: 
30:           runners = {
31:             caliptra-sw = caliptra-sw-env.packages.${system}.default;
32:             opentitan = opentitan-env.packages.${system}.default;
33:             caliptra-mcu-sw = caliptra-mcu-sw-env.packages.${system}.default;
34:             caliptra-dpe = caliptra-dpe-env.packages.${system}.default;
35:             tests = tests-env.packages.${system}.default;
36:           };
37: 
38:           google-genai-latest = pkgs.python3Packages.google-genai.overridePythonAttrs (old: rec {
39:             version = "2.10.0";
40:             src = pkgs.python3Packages.fetchPypi {
41:               pname = "google_genai";
42:               inherit version;
43:               hash = "sha256-d5Es1VjNff1bdcJf0cYJ5415VN3lgzMRBAIqRuqQ+e4=";
44:             };
45:             doCheck = false;
46:           });
47: 
48:           google-adk = pkgs.python3Packages.buildPythonPackage {
49:             pname = "google-adk";
50:             version = "2.4.0";
51:             pyproject = true;
52:             src = pkgs.python3Packages.fetchPypi {
53:               pname = "google_adk";
54:               version = "2.4.0";
55:               hash = "sha256-WimWsojVkd7vyyd+7ut9qDjXIFZnV2O/71KtOzaXXd4=";
56:             };
57:             postPatch = import ./nix/adk_telemetry_patch.nix;
58:             nativeBuildInputs = with pkgs.python3Packages; [
59:               flit-core
60:             ];
61:             dontCheckRuntimeDeps = true;
62:             dependencies = with pkgs.python3Packages; [
63:               google-genai-latest
64:               pydantic
65:               aiosqlite
66:               authlib
67:               fastapi
68:               click
69:               jsonschema
70:               pyyaml
71:               python-dotenv
72:               python-multipart
73:               uvicorn
74:               websockets
75:               watchdog
76:               tzlocal
77:               opentelemetry-api
78:               opentelemetry-sdk
79:               packaging
80:             ];
81:             pythonImportsCheck = [ "google.adk" ];
82:             doCheck = false;
83:           };
84: 
85:           pythonEnv = pkgs.python3.withPackages (ps: [
86:             ps.pydantic
87:             google-genai-latest
88:             ps.google-cloud-storage
89:             ps.pyopenssl
90:             ps.tqdm
91:             ps.pandas
92:             ps.openpyxl
93:             ps.tabulate
94:             google-adk
95:           ]);
96: 
97:           mjolnir-app = pkgs.stdenv.mkDerivation {
98:             name = "mjolnir-app";
99:             src = ./app/mjolnir;
100:             
101:             nativeBuildInputs = [ pkgs.makeWrapper ];
102:             
103:             installPhase = ''
104:               mkdir -p $out/bin $out/lib
105:               cp -r * $out/lib/
106:               
107:               makeWrapper ${pythonEnv}/bin/python3 $out/bin/mjolnir-run \
108:                 --add-flags "$out/lib/main.py" \
109:                 --prefix PYTHONPATH : "$out/lib" \
110:                 --prefix PATH : "${pkgs.lib.makeBinPath [ pkgs.git pkgs.ripgrep pkgs.universal-ctags pkgs.ast-grep ]}" \
111:                 --set GOOGLE_API_USE_CLIENT_CERTIFICATE false
112:             '';
113:           };
114: 
115:           makeJob = { project, job, runner ? null }: 
116:             import ./nix/orchestrator.nix {
117:               inherit pkgs project job runner mjolnir-app;
118:             };
119: 
120:           makeGroup = { name, description, jobs }:
121:             import ./nix/group.nix { inherit pkgs; } {
122:               inherit name description jobs;
123:             };
124: 
125:           discovered = autodiscoverJobs { inherit pkgs makeJob runners; };
126: 
127:           caliptra-sw-runner-test = makeJob {
128:             project = import ./projects/caliptra-sw/project.nix;
129:             job = import ./projects/caliptra-sw/nix/runner-test.nix;
130:             runner = runners.caliptra-sw;
131:           };
132: 
133:           caliptra-mcu-sw-runner-test = makeJob {
134:             project = import ./projects/caliptra-mcu-sw/project.nix;
135:             job = import ./projects/caliptra-mcu-sw/nix/runner-test.nix;
136:             runner = runners.caliptra-mcu-sw;
137:           };
138: 
139:           caliptra-dpe-runner-test = makeJob {
140:             project = import ./projects/caliptra-dpe/project.nix;
141:             job = import ./projects/caliptra-dpe/nix/runner-test.nix;
142:             runner = runners.caliptra-dpe;
143:           };
144: 
145:           opentitan-runner-host-test = makeJob {
146:             project = import ./projects/opentitan/project.nix;
147:             job = import ./projects/opentitan/nix/runner-host-test.nix;
148:             runner = runners.opentitan;
149:           };
150: 
151:           opentitan-runner-verilator-test = makeJob {
152:             project = import ./projects/opentitan/project.nix;
153:             job = import ./projects/opentitan/nix/runner-verilator-test.nix;
154:             runner = runners.opentitan;
155:           };
156: 
157:           gen-dashboard = pkgs.writeShellApplication {
158:             name = "mjolnir-gen-dashboard";
159:             runtimeInputs = [ mjolnir-app ];
160:             text = ''
161:               mjolnir-run --gen-dashboard "$@"
162:             '';
163:           };
164:         in
165:           discovered // {
166:             inherit
167:               mjolnir-app
168:               gen-dashboard
169:               caliptra-sw-runner-test
170:               caliptra-mcu-sw-runner-test
171:               caliptra-dpe-runner-test
172:               opentitan-runner-host-test
173:               opentitan-runner-verilator-test;
174: 
175:             test-all = makeGroup {
176:               name = "test-all";
177:               description = "All tests";
178:               jobs = [
179:                 discovered.mock-smoke-test
180:                 discovered.mock-gcs-test
181:                 discovered.genai-gemini-test
182:                 discovered.genai-gemini-gcs-test
183:                 discovered.adk-gemini-test
184:                 discovered.adk-gemini-gcs-test
185:                 discovered.adk-gemini-ingest-test
186:               ];
187:             };
188: 
189:             test-all-runners = makeGroup {
190:               name = "test-all-runners";
191:               description = "All runner tests";
192:               jobs = [
193:                 caliptra-sw-runner-test
194:                 caliptra-mcu-sw-runner-test
195:                 caliptra-dpe-runner-test
196:                 opentitan-runner-host-test
197:                 opentitan-runner-verilator-test
198:               ];
199:             };
200: 
201:             caliptra-all = makeGroup {
202:               name = "caliptra-all";
