TEST_SV = """module keymgr_input_checks (
  input  logic key_vld_in,
  input  logic [255:0] key_share0,
  input  logic [255:0] key_share1,
  output logic key_vld_o
);
  assign key_vld_o = |key_share0 && |key_share1;
endmodule
"""


def _has_api_key():
